def field(fid: str) -> dict:
    """Return the extracted metadata for one REopt form field id."""
    return FIELDS.get(fid, {})


def options(fid: str) -> list[tuple[str, str]]:
    """(value, label) pairs in the tool's own order, blank entries removed."""
    opts = FIELDS.get(fid, {}).get('options') or []
    return [(v, t) for v, t in opts if v != '']


def panel_fields(panel: str) -> list[dict]:
    return [f for f in FIELDS.values() if f['panel'] == panel]
